t-shadow:0 2px 6px #001}.quest-card{position:absolute;z-index:2;left:22px;top:115px;display:flex;gap:11px;align-items:center;padding:11px 14px;border:1px solid var(--line);background:#08233bba;backdrop-filter:blur(10px);border-radius:15px;min-width:205px}.quest-icon{width:34px;height:34px;display:grid;place-items:center;background:#40bcbd23;border-radius:11px;font-size:18px}.quest-card small{display:block;font-size:8px;color:#8daec3;letter-spacing:1.2px;font-weight:800}.quest-card b{display:block;font-size:11px;margin-top:4px}.quest-card em{font-style:normal;color:var(--aqua);margin-left:7px}.quest-track{width:130px;height:3px;border-radius:4px;background:#24435a;margin-top:7px}.quest-track i{height:100%;display:block;width:0;background:#62e1d8;border-radius:4px;transition:width .3s}.controls{position:absolute;inset:0;pointer-events:none;z-index:3}.move-zone{position:absolute;left:0;bottom:75px;width:46%;height:44%;pointer-events:auto;touch-action:none}.joy-base{position:absolute;width:112px;height:112px;left:28px;bottom:23px;border:1px solid #d9faff49;border-radius:50%;background:#08294561;display:none;backdrop-filter:blur(4px);box-shadow:inset 0 0 22px #4cc5d428}.joy-knob{position:absolute;left:50%;top:50%;width:48px;height:48px;transform:translate(-50%,-50%);border-radius:50%;background:linear-gradient(145deg,#a4fff2d9,#51bdcda8);border:1px solid #e3ffffa6;box-shadow:0 4px 16px #36b9c066}.action-pad{position:absolute;right:22px;bottom:98px;width:170px;height:148px;pointer-events:none}.control-btn{position:absolute;pointer-events:auto;width:61px;height:61px;border:1px solid #dcfaff55;border-radius:21px;background:linear-gradient(145deg,#113e59cc,#092741d9);backdrop-filter:blur(9px);box-shadow:0 8px 22px #00162670,inset 0 1px #ffffff18;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:1px;touch-action:none}.control-btn span{font-size:22px;line-height:24px}.control-btn small{font-size:7px;font-weight:800;letter-spacing:1px;color:#c0d8e