;pointer-events:none;text-align:center;padding:14px 22px;border-radius:16px;background:linear-gradient(135deg,#102d45ed,#09233dee);border:1px solid #71e9d8a8;box-shadow:0 0 35px #24cbb24d;transition:.3s}.catch-toast.show{opacity:1;transform:translate(-50%,0)}.catch-toast b{display:block;font:700 18px Outfit}.catch-toast small{color:#a6c5d4}.toast{position:absolute;z-index:20;left:50%;bottom:90px;transform:translate(-50%,10px);padding:10px 16px;background:#06192af2;border:1px solid var(--line);border-radius:12px;color:#dff7f8;font-size:12px;opacity:0;transition:.2s;pointer-events:none}.toast.show{opacity:1;transform:translate(-50%,0)}.screen{position:absolute;z-index:10;inset:0;display:none;align-items:center;justify-content:center;background:#0315258c;backdrop-filter:blur(7px);padding:20px}.screen.visible{display:flex}.menu-art{position:absolute;inset:0;background:linear-gradient(180deg,#0d3553 0%,#236986 43%,#56b2a7 100%);overflow:hidden}.menu-art:before{content:"";position:absolute;inset:0;background:radial-gradient(ellipse at 70% 22%,#f9d99d91 0,transparent 23%),linear-gradient(180deg,transparent 44%,#11475d 45%,#0d344a 100%)}.menu-art:after{content:"";position:absolute;left:-5%;right:-5%;height:39%;bottom:-1%;background:repeating-linear-gradient(175deg,transparent 0 34px,#66d1c112 36px 39px),linear-gradient(180deg,#18728b 0%,#092c49 100%);border-radius:50% 50% 0 0/14% 14% 0 0}.sun-glow{position:absolute;width:270px;height:270px;border-radius:50%;background:#ffdca52c;top:8%;left:62%;filter:blur(5px)}.menu-logo{position:absolute;left:10%;top:24%;z-index:2}.menu-logo span{color:#90f4df;font-size:30px}.menu-logo h1{font:800 clamp(44px,8vw,95px)/.9 Outfit;letter-spacing:9px;margin:9px 0;text-shadow:0 6px 25px #06334777}.menu-logo p{font-size:11px;letter-spacing:5px;color:#c5f7f1;margin:18px 0}.menu-caption{position:absolute;left:10%;top:57%;font-size:14px;color:#d1ede9;z-index:2}.menu-fish{position:absolute;z-index:1;color:#ffcf8a;font-size:45px;filter:drop-shadow(0 5px 8px #06344866);animation:floatFish 4s ease-in-out infinite}.fish-a{left:60%;top:43%;transform:rotate(-25deg)}.fish-b{left:76%;top:56%;font-size:28px;color:#bdffe2;animation-delay:-2s}@keyframes floatFish{50%{translate:0 -16px;rotate:7deg}}.menu-card{position:relative;z-index:3;margin-left:auto;margin-right:6%;width:310px;padding:30px 28px;border:1px solid #d9f8ff3b;border-radius:22px;background:#071e33e8;box-shadow:0 25px 80px #06182877;backdrop-filter:blur(18px)}.eyebrow{font-size:9px;font-weight:800;letter-spacing:2px;color:#6ce3d7}.menu-card h2,.modal-card h2{font:700 29px Outfit;margin:8px 0}.menu-card p{color:#a8c0ce;font-size:12px;line-height:1.6;margin:0 0 22px}.primary-btn{width:100%;padding:14px 16px;border-radius:12px;background:linear-gradient(100deg,#67e3d3,#55b7dc);color:#06354a;font-size:11px;font-weight:900;letter-spacing:1px;text-align:left;box-shadow:0 8px 22px #32c4c747}.primary-btn span{float:right;font-size:17px;line-height:11px}.local-note{display:flex;align-items:center;gap:7px;margin-top:17px;color:#9bb7c8;font-size:8px;letter-spacing:.8px}.local-note i{width:6px;height:6px}.text-btn{display:block;background:none;color:#80dcd7;font-size:11px;margin:15px auto 0}.slot-card,.panel-card{position:relative;width:min(520px,96vw);max-height:min(84vh,730px);overflow:auto;padding:28px;border-radius:22px;border:1px solid #b8e8f536;background:linear-gradient(145deg,#0b2a43f5,#061b30f7);box-shadow:0 24px 80px #00101c99}.close-btn{position:absolute;right:17px;top:17px;font-size:24px;background:#12344b}.muted{color:#91adbf;font-size:12px;margin:5px 0 18px}.slot-list{display:grid;gap:9px}.slot-row{display:flex;align-items:center;gap:12px;padding:13px;border:1px solid #b9e6f322;background:#0e3048;border-radius:14px}.slot-num{width:38px;height:38px;border-radius:12px;display:grid;place-items:center;background:#164965;color:#83ebdb;font:700 15px Outfit}.slot-info{flex:1}.slot-info b{display:block;font-size:12px}.slot-info small{color:#9ab7c8;font-size:10px}.slot-row button{padding:9px 12px;border-radius:9px;background:#43c9bd;color:#07344a;font-weight:800;font-size:9px}.slot-row button.secondary{background:#183c53;color:#c0d7e3}.panel-title{font:700 24px Outfit;margin:3px 0 5px}.tabs{display:flex;gap:5px;flex-wrap:wrap;margin:18px 0 14px}.tab{padding:8px 11px;border:1px solid var(--line);border-radius:9px;background:#102f47;color:#a8c2d0;font-size:10px}.tab.active{background:#43bcb7;color:#062e40;border-color:#76eee0}.panel-body{min-height:180px}.item-list{display:grid;gap:8px}.item-row{display:flex;align-items:center;gap:10px;padding:10px;border:1px solid #b9e6f21c;border-radius:12px;background:#0c2b43}.item-icon{width:38px;height:38px;border-radius:10px;display:grid;place-items:center;font-size:21px;background:#18445b}.item-row .item-desc{flex:1}.item-row b{display:block;font-size:11px}.item-row small{font-size:9px;color:#94b1c1}.item-row button{background:#236776;border-radius:8px;padding:8px 10px;font-size:9px;font-weight:800}.stat-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:8px;margin:14px 0}.stat{padding:12px;border-radius:12px;background:#103149}.stat small{display:block;color:#94b4c5;font-size:9px}.stat b{font:700 18px Outfit;color:#8ce5dc}.setting-row{display:flex;justify-content:space-between;align-items:center;padding:12px 0;border-bottom:1px solid #b9e6f21c;font-size:11px}.setting-row input[type=range]{width:120px;accent-color:#58d4c9}.setting-row select,.setting-row input[type=text]{background:#102f47;color:#dff;border:1px solid var(--line);border-radius:7px;padding:6px}.shop-grid{display:grid;grid-template-columns:1fr 1fr;gap:10px}.shop-card{padding:14px;border:1px solid #b9e6f22a;border-radius:13px;background:#0d3048}.shop-card .big{font-size:24px}.shop-card b{display:block;font-size:11px;margin:5px 0}.shop-card small{display:block;color:#9ab5c5;min-height:29px;font-size:9px}.shop-card button{margin-top:9px;width:100%;padding:8px;border-radius:8px;background:#41bdb4;color:#062c3a;font-size: