@media(orientation:portrait){.action-pad{bottom:88px}.move-zone{bottom:62px;height:39%}.bottom-ui{justify-content:center}.tool-switch{position:absolute;left:0;bottom:0}.bottom-actions{position:absolute;right:0;bottom:0}.hotbar{margin-bottom:0}.quest-card{top:88px}.world-note{top:64px}}
@media(max-height:500px) and (orientation:landscape){.quest-card{top:90px;transform:scale(.78);transform-origin:top left}.world-note{top:69px}.action-pad{bottom:76px;transform:scale(.78)}.move-zone{bottom:60px;height:52%}.bottom-ui{bottom:7px}.hot-slot{width:39px;height:39px}.tool-switch button,.round-btn{height:40px}.menu-card{padding:18px 22px;width:285px}.menu-card h2{font-size:23px}.menu-card p{margin-bottom:12px}}

(() => {
'use strict';
const canvas=document.querySelector('#world'),ctx=canvas.getContext('2d');
const $=s=>document.querySelector(s), clamp=(v,a,b)=>Math.max(a,Math.min(b,v));
const BIOMES=[
 {name:'CRIMSON ABYSS',color:'#b94663',deep:'#401c48',accent:'#ff8a88',fish:['Anglerfish','Crimson Lanternfish','Bloodfin Eel','Red Abyss Bass','Shadow Angler'],diff:'EXPERT',sky:['#422b56','#a44d69'],decor:'crimson'},
 {name:'EMERALD GROVE',color:'#48aa83',deep:'#145c5b',accent:'#abf19b',fish:['Common Carp','Emerald Carp','Golden Grass Carp','Mossback Koi','Ancient Forest Carp'],diff:'RELAXED',sky:['#347c70','#83be86'],decor:'green'},
 {name:'CRYSTAL BLUE OCEAN',color:'#329fd0',deep:'#124b80',accent:'#9deeff',fish:['Bluefin Tuna','Giant Tuna','Silver Marlin','Crystal Mackerel','Oceanic Sailfish'],diff:'CHALLENGING',sky:['#2875a1','#85d4d7'],decor:'blue'},
 {name:'TURQUOISE WATERS',color:'#3dc6bf',deep:'#116580',accent:'#b0fff0',fish:['Butterflyfish','Clownfish','Blue Tang','Guppy','Rainbow Fish','Small Snapper','Tropical Bass'],diff:'BEGINNER',sky:['#318ca7','#9bd9c7'],decor:'tropical'}
];
const FISH={
 'Anglerfish':[2,65,58,'Epic'],'Crimson Lanternfish':[.1,2.4,32,'Rare'],'Bloodfin Eel':[1,24,46,'Epic'],'Red Abyss Bass':[2,18,38,'Rare'],'Shadow Angler':[8,80,88,'Legendary'],
 'Common Carp':[.4,8,12,'Common'],'Emerald Carp':[1,14,24,'Rare'],'Golden Grass Carp':[3,28,40,'Epic'],'Mossback Koi':[.3,12,30,'Rare'],'Ancient Forest Carp':[10,95,84,'Legendary'],
 'Bluefin Tuna':[20,140,68,'Epic'],'Giant Tuna':[50,240,100,'Legendary'],'Silver Marlin':[12,90,55,'Epic'],'Crystal Mackerel':[.2,3.8,20,'Common'],'Oceanic Sailfish':[18,120,70,'Legendary'],
 'Butterflyfish':[.01,.25,5,'Common'],'Clownfish':[.02,.35,7,'Common'],'Blue Tang':[.1,1.8,12,'Common'],'Guppy':[.01,.08,3,'Common'],'Rainbow Fish':[.1,2.5,30,'Rare'],'Small Snapper':[.3,4,14,'Common'],'Tropical Bass':[1,10,20,'Rare']};
const RODS=[['Wooden Starter Rod','🪵','Common',1,1],['Bent Bamboo Rod','🎋','Common',1.1,1.1],['Emerald Reed Rod','🌿','Rare',1.3,1.2],['Coral Explorer Rod','🪸','Rare',1.25,1.25],['Phantom Current Rod','🌌','Epic',1.6,1.5],['Thunder Reel Rod','⚡','Epic',1.7,1.4],['Leviathan Rod','🔱','Legendary',2,1.9],['Celestial Tide Rod','✨','Legendary',1.9,2],['Abyssal Monarch','🦑','Mythical',2.4,2.5],['Poseidon’s Wrath','🌊','Godly',3,3]];
const ACCESSORIES=[['Lucky Fisher Hat','🧢','Head',1.12],['Golden Crown','👑','Head',1.25],['Deep Sea Diver Helmet','🤿','Head',1.18],['Mini Aquarium Backpack','🐠','Back',1.15],['Lucky Pearl','🦪','Charm',1.14],['Ancient Compass','🧭','Charm',1.2],['Fisherman’s Grip','🧤','Gloves',1.2],['Dolphin Boots','🐬','Boots',1.12]];
const LURES=[['Basic Worm','🪱','All fish'],['Golden Worm','✨','More rare fish'],['Red Glow Bait','🔴','Abyss fish'],['Emerald Leaf Lure','🍃','Carp'],['Crystal Spinner','💠','Ocean fish'],['Tuna Hunter Lure','🌀','Tuna'],['Rainbow Popper','🌈','Tropical fish'],['Electric Jelly Lure','🪼','Rare fish']];
const RARITY=['Common','Rare','Epic','Legendary','Mythical','Godly'],ODDS=[45,27,15,8,4,1];
const defaultSave=(name='New Angler')=>({name,created:Date.now(),x:302,gems:120,inventory:[{name:'Wooden Starter Rod',type:'rod',qty:1,icon:'🪵'},{name:'Basic Worm',type:'bait',qty:12,icon:'🪱'},{name:'Emerald Leaf Lure',type:'lure',qty:2,icon:'🍃'},{name:'Seaweed Block',type:'block',qty:24,icon:'🌿'},{name:'Coral Decoration',type:'decoration',qty:8,icon:'🪸'}],equipped:'Wooden Starter Rod',accessories:[],discovered:{},records:{},totalWeight:0,totalCaught:0,pity:0,settings:{sensitivity:1,opacity:1,controller:'Floating Analog',music:55,sfx:75},quest:0,build:false});
let save=null,slotIndex=-1,keys={},last=0,cam=0,view={w:960,h:540,dpr:1},player={x:302,y:0,vx:0,vy:0,face:1,onGround:false,frame:0},joystick={active:false,id:null,x:0,y:0,dx:0},mode='FIST',selected=0,fishState='idle',biteTimer=0,catchData=null,minigame=null,cast={x:0,y:0,phase:0},particles=[],worldTime=0,panelTab='';
const slotKey=i=>`aquaria_save_${i}`;
function loadSlot(i){try{return JSON.parse(localStorage.getItem(slotKey(i)))}catch{return null}}
function persist(){if(save&&slotIndex>=0){localStorage.setItem(slotKey(slotIndex),JSON.stringify(save));}}
function toast(msg){const el=$('#toast');el.textContent=msg;el.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.classList.remove('show'),2100)}
function resize(){const r=canvas.getBoundingClientRect();view.w=r.width;view.h=r.height;view.dpr=Math.min(devicePixelRatio||1,2);canvas.width=Math.round(r.width*view.dpr);canvas.height=Math.round(r.height*view.dpr);ctx.setTransform(view.dpr,0,0,view.dpr,0,0)}window.addEventListener('resize',resize);resize();
function biomeAt(x){return BIOMES[clamp(Math.floor(x/1000),0,3)]}function biomeIndex(x){return clamp(Math.floor(x/1000),0,3)}
function setupGame(){player.x=save.x||302;player.y=330;player.vy=0;cam=0;$('#menuScreen').classList.remove('visible');$('#slotsScreen').classList.remove('visible');renderHotbar();updateHud();persist()}
