function openInventory(){panel('Angler’s pack',`<div class="tabs"><button class="tab active" data-tab="Inventory">Inventory</button><button class="tab" data-tab="Equipment">Equipment</button><button class="tab" data-tab="Collection">Collection</button><button class="tab" data-tab="Records">Records</button></div><div class="panel-body" id="inventoryBody"></div>`);renderInventory('Inventory');document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-tab]').forEach(x=>x.classList.toggle('active',x===b));renderInventory(b.dataset.tab)})}
function renderInventory(tab){const body=$('#inventoryBody');if(!body)return;if(tab==='Inventory'){body.innerHTML=`<div class="item-list">${save.inventory.map((it,i)=>`<div class="item-row"><div class="item-icon">${it.icon}</div><div class="item-desc"><b>${it.name}</b><small>${it.type} · ×${it.qty}${it.name===save.equipped?' · equipped':''}</small></div><button data-equip="${i}">${it.type==='rod'?'EQUIP':'USE'}</button><button class="secondary" data-drop="${i}">DROP</button></div>`).join('')||'<p class="muted">Your pack is empty.</p>'}</div><p class="muted">Tap an item to move it to the hotbar. Dropped items remain in this world.</p>`;body.querySelectorAll('[data-equip]').forEach(b=>b.onclick=()=>{const it=save.inventory[+b.dataset.equip];if(it.type==='rod'){save.equipped=it.name;persist();toast(`${it.name} equipped`);openInventory()}else if(it.type==='bait'||it.type==='lure'){useItem(it);openInventory()}else toast(`${it.name} is ready to use`)});body.querySelectorAll('[data-drop]').forEach(b=>b.onclick=()=>dropItem(+b.dataset.drop));body.querySelectorAll('.item-row').forEach((r,i)=>r.onclick=e=>{if(e.target.tagName==='BUTTON')return;const item=save.inventory[i];if(i<8){selected=i}else{const empty=save.inventory.findIndex((it,j)=>j<8&&!it);if(empty>=0){[save.inventory[i],save.inventory[empty]]=[save.inventory[empty],save.inventory[i]];selected=empty}else toast('Hotbar is full')}renderHotbar();persist();renderInventory('Inventory')})}else if(tab==='Equipment'){body.innerHTML=`<div class="stat-grid"><div class="stat"><small>ACTIVE ROD</small><b>${save.equipped}</b></div><div class="stat"><small>ROD POWER</small><b>${(RODS.find(r=>r[0]===save.equipped)||RODS[0])[3]}×</b></div><div class="stat"><small>ACCESSORY BUFF</small><b>${save.accessories.length?`${(1+save.accessories.length*.08).toFixed(2)}×`:'—'}</b></div></div><div class="item-list">${save.accessories.map((a,i)=>`<div class="item-row"><div class="item-icon">${a.icon}</div><div class="item-desc"><b>${a.name}</b>