function pull(type){const cost=type==='rod'?45:35;if(save.gems<cost){toast('Not enough gems');return}save.gems-=cost;let tierRoll=Math.random()*100,idx=ODDS.findIndex((v,i)=>{tierRoll-=v;return tierRoll<0});idx=Math.max(0,idx);save.pity++;if(save.pity>=200)idx=Math.max(idx,4);else if(save.pity>=100)idx=Math.max(idx,3);else if(save.pity>=50)idx=Math.max(idx,2);const tier=RARITY[idx],pool=type==='rod'?RODS.filter(r=>r[2]===tier):ACCESSORIES.filter(a=>{const n=['Common','Rare','Epic','Legendary','Mythical','Godly'][Math.min(5,Math.floor((a[3]-1)*10))];return n===tier});let reward=pool[Math.floor(Math.random()*pool.length)];if(!reward){reward=type==='rod'?RODS[Math.min(RODS.length-1,idx*2)]:ACCESSORIES[Math.min(ACCESSORIES.length-1,idx)]}const name=reward[0],icon=reward[1],existing=type==='rod'?save.inventory.some(i=>i.name===name):save.accessories.some(i=>i.name===name);let message;if(existing){save.gems+=10;message=`Duplicate ${name} · converted to 10 gems`}else if(type==='rod'){save.inventory.push({name,type:'rod',qty:1,icon});message=`${tier} · ${name}`}else{save.accessories.push({name,icon,slot:reward[2],buff:reward[3],rarity:tier});message=`${tier} · ${name} added to equipment`}persist();updateHud();openShop();toast(message);}
